// Package manifest reads modules.yaml, the migration's progress record
// (generated by scripts/gen-modules.py; only `status` and `jobs` are edited by hand),
// and checks it against the route inventory.
package manifest

import (
	"encoding/json"
	"fmt"
	"os"
	"slices"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

type Status string

const (
	Swift      Status = "swift"
	Parity     Status = "parity"
	Staging    Status = "staging"
	Production Status = "production"
	Done       Status = "done"
)

type Module struct {
	Wave           int      `yaml:"wave"`
	SwiftDir       string   `yaml:"swiftDir"`
	Status         Status   `yaml:"status"`
	Prefixes       []string `yaml:"prefixes"`
	ExactPaths     []string `yaml:"exactPaths"`
	SharedPrefixes []string `yaml:"sharedPrefixes"`
	// StringPrefixCatches lists other modules' paths that this module's prefixes
	// catch only as plain strings ("/v1/vault" catches "/v1/vaults"). A flip must
	// name them explicitly in ingress.
	StringPrefixCatches []string   `yaml:"stringPrefixCatches"`
	HeldPaths           []HeldPath `yaml:"heldPaths"`
	FlipsWith           []string   `yaml:"flipsWith"`
	Jobs                []string   `yaml:"jobs"`
}

// HeldPath is a route (and anything under it) that stays on Swift when its
// module flips, by an explicit ingress entry. It's out of the module's G1 and in
// the G1 of the group that releases it.
type HeldPath struct {
	Path       string `yaml:"path"`
	Reason     string `yaml:"reason"`
	ReleasedBy string `yaml:"releasedBy"`
}

type Manifest struct {
	Modules map[string]Module `yaml:"modules"`
}

func Load(path string) (Manifest, error) {
	raw, err := os.ReadFile(path) //nolint:gosec // repo-relative manifest path
	if err != nil {
		return Manifest{}, err
	}
	var m Manifest
	if err := yaml.Unmarshal(raw, &m); err != nil {
		return Manifest{}, fmt.Errorf("manifest: %w", err)
	}
	for name, mod := range m.Modules {
		switch mod.Status {
		case Swift, Parity, Staging, Production, Done:
		default:
			return Manifest{}, fmt.Errorf("manifest: module %s has unknown status %q", name, mod.Status)
		}
		for _, h := range mod.HeldPaths {
			if h.Path == "" || h.Reason == "" || h.ReleasedBy == "" {
				return Manifest{}, fmt.Errorf("manifest: module %s has a held path without path, reason or releasedBy: %+v", name, h)
			}
		}
	}
	return m, nil
}

// Route is one entry of docs/migration/routes.json.
type Route struct {
	Method string `json:"method"`
	Path   string `json:"path"`
	Module string `json:"module"`
}

// LoadRoutes reads the route inventory.
func LoadRoutes(path string) ([]Route, error) {
	raw, err := os.ReadFile(path) //nolint:gosec // repo-relative inventory path
	if err != nil {
		return nil, err
	}
	var routes []Route
	if err := json.Unmarshal(raw, &routes); err != nil {
		return nil, fmt.Errorf("manifest: %w", err)
	}
	return routes, nil
}

func segments(p string) []string { return strings.FieldsFunc(p, func(r rune) bool { return r == '/' }) }

// ElementMatch is the Kubernetes Ingress definition of Prefix: whole path
// elements. A route's {param} or *wildcard element matches any literal.
func ElementMatch(prefix, route string) bool {
	pre, p := segments(prefix), segments(route)
	if len(pre) > len(p) {
		return false
	}
	for i := range pre {
		if pre[i] != p[i] && !strings.HasPrefix(p[i], "{") && !strings.HasPrefix(p[i], "*") {
			return false
		}
	}
	return true
}

// StringMatch is what Traefik does with `pathType: Prefix` when
// strictPrefixMatching is off, its default and the chart's setting:
// "/v1/vault" also matches "/v1/vaults".
func StringMatch(prefix, route string) bool { return strings.HasPrefix(route, prefix) }

// PrefixMatch reports whether an ingress prefix can send route to its backend,
// under either behaviour.
func PrefixMatch(prefix, route string) bool {
	return ElementMatch(prefix, route) || StringMatch(prefix, route)
}

// under is literal path containment: route is path or sits below it. Parameters
// aren't wildcards here, so holding /v1/memory/search doesn't hold /v1/memory/{id}.
func under(path, route string) bool {
	return route == path || strings.HasPrefix(route, path+"/")
}

func (m Module) holds(route string) bool {
	return slices.ContainsFunc(m.HeldPaths, func(h HeldPath) bool { return under(h.Path, route) })
}

// catches reports whether route is declared as caught only as a string.
func (m Module) catches(route string) bool {
	return slices.ContainsFunc(m.StringPrefixCatches, func(p string) bool { return under(p, route) || ElementMatch(p, route) })
}

// Check verifies that flipping a module moves its own routes and nothing else:
//
//   - every route has exactly one owner, or sits under a shared prefix;
//   - a prefix that catches another module's route only as a string declares it
//     in stringPrefixCatches, and a declaration catches something real;
//   - a route under a module's prefix that another module owns is held;
//   - a held path is a real route the module's own entries cover.
//
// It returns every violation.
func (m Manifest) Check(routes []Route) []error {
	var errs []error
	report := func(format string, args ...any) { errs = append(errs, fmt.Errorf(format, args...)) }
	names := make([]string, 0, len(m.Modules))
	for name := range m.Modules {
		names = append(names, name)
	}
	sort.Strings(names)

	for _, r := range routes {
		var owners []string
		shared := false
		for _, name := range names {
			mod := m.Modules[name]
			claimed := slices.Contains(mod.ExactPaths, r.Path)
			for _, p := range mod.Prefixes {
				switch {
				case ElementMatch(p, r.Path):
					claimed = claimed || !mod.holds(r.Path)
				case StringMatch(p, r.Path) && !mod.claimsByElement(r.Path):
					if !mod.catches(r.Path) {
						report("%s: prefix %s catches %s %s as a string; declare it in stringPrefixCatches", name, p, r.Method, r.Path)
					}
				}
			}
			for _, p := range mod.SharedPrefixes {
				shared = shared || ElementMatch(p, r.Path)
				if !ElementMatch(p, r.Path) && StringMatch(p, r.Path) && !mod.claimsByElement(r.Path) && !mod.catches(r.Path) {
					report("%s: shared prefix %s catches %s %s as a string; declare it in stringPrefixCatches", name, p, r.Method, r.Path)
				}
			}
			if claimed {
				owners = append(owners, name)
			}
		}
		switch {
		case len(owners) > 1:
			report("%s %s is claimed by several modules: %v", r.Method, r.Path, owners)
		case len(owners) == 0 && !shared:
			report("%s %s (%s) is not covered by any prefix", r.Method, r.Path, r.Module)
		}
	}

	for _, name := range names {
		mod := m.Modules[name]
		for _, c := range mod.StringPrefixCatches {
			if !slices.ContainsFunc(routes, func(r Route) bool { return under(c, r.Path) && !mod.claimsByElement(r.Path) }) {
				report("%s: stringPrefixCatches %s catches no other module's route", name, c)
			}
			if !slices.ContainsFunc(append(append([]string{}, mod.Prefixes...), mod.SharedPrefixes...), func(p string) bool { return StringMatch(p, c) }) {
				report("%s: stringPrefixCatches %s is under none of its prefixes", name, c)
			}
		}
		for _, h := range mod.HeldPaths {
			if !slices.ContainsFunc(routes, func(r Route) bool { return under(h.Path, r.Path) }) {
				report("%s: held path %s is no route", name, h.Path)
			}
			if !mod.claimsByElement(h.Path) {
				report("%s: held path %s is not under any of its own entries", name, h.Path)
			}
		}
	}
	return errs
}

// claimsByElement reports whether one of the module's own entries covers route
// by path element, so a string match is the module's own business.
func (m Module) claimsByElement(route string) bool {
	if slices.Contains(m.ExactPaths, route) {
		return true
	}
	return slices.ContainsFunc(append(append([]string{}, m.Prefixes...), m.SharedPrefixes...), func(p string) bool { return ElementMatch(p, route) })
}

func (m Module) covers(path string) bool { return m.claimsByElement(path) }
